import{_ as t,o as r,c as o,a2 as a}from"./chunks/framework.il0noOp3.js";const f=JSON.parse('{"title":"Power Platform Solution Assessment — enumerated question set","description":"","frontmatter":{},"headers":[],"relativePath":"frameworks/power-platform-solution-question-set.md","filePath":"frameworks/power-platform-solution-question-set.md"}'),n={name:"frameworks/power-platform-solution-question-set.md"};function i(l,e,s,d,c,p){return r(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="power-platform-solution-assessment-—-enumerated-question-set" tabindex="-1">Power Platform Solution Assessment — enumerated question set <a class="header-anchor" href="#power-platform-solution-assessment-—-enumerated-question-set" aria-label="Permalink to &quot;Power Platform Solution Assessment — enumerated question set&quot;">​</a></h1><p><strong>Enumerated 2026-11-25. Verification method and limits are stated below — read them before quoting any coverage number from this page.</strong></p><p>Scout&#39;s <code>pp.solution.yaml</code> scores Microsoft&#39;s <a href="https://learn.microsoft.com/en-us/assessments/a5c3b65d-bf7e-4743-850a-0437ae692690/" target="_blank" rel="noreferrer">Power Platform Solution Assessment</a>, a review of a solution from its functionality and user experience through to its alignment with business goals. <code>src/assess/rules/pp.solution.yaml</code> is written against this page only, and every rule cites an item from the tables below.</p><h2 id="source" tabindex="-1">Source <a class="header-anchor" href="#source" aria-label="Permalink to &quot;Source&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Assessment</td><td><a href="https://learn.microsoft.com/en-us/assessments/a5c3b65d-bf7e-4743-850a-0437ae692690/" target="_blank" rel="noreferrer">Power Platform Solution Assessment</a> (60 minutes, multiple choice and multiple response; question text not published)</td></tr><tr><td>Framework version</td><td>Power Platform ALM, adoption and Well-Architected guidance on Microsoft Learn, current; the assessment itself is unversioned and its questions are unpublished</td></tr><tr><td>Extraction date</td><td>2026-11-25</td></tr><tr><td>Verification method</td><td>The assessment page, the Power Platform guidance landing page, the adoption overview pages and the Well-Architected pillar checklists named under Sources were fetched in full with the Microsoft Learn MCP <code>microsoft_docs_fetch</code> tool on 2026-11-25. ALM and several adoption articles were read as Microsoft Learn search excerpts only, as marked. Power Platform API and Dataverse names in the last section were checked against the Learn permission reference, REST reference overview and Dataverse table reference.</td></tr></tbody></table><h2 id="the-questions-are-scout-derived" tabindex="-1">The questions are Scout-derived <a class="header-anchor" href="#the-questions-are-scout-derived" aria-label="Permalink to &quot;The questions are Scout-derived&quot;">​</a></h2><p><strong>This is not Microsoft&#39;s question list.</strong> Microsoft describes the assessment as covering &quot;every aspect of the solution, from functionality and user experience to its alignment with overall business goals&quot; and publishes neither its questions nor their numbering. Unlike the Well-Architected assessment there is no single published checklist behind it. The items below are <strong>Scout&#39;s</strong> reading of the Power Platform guidance named per row (application lifecycle management, the adoption guidance and the Well-Architected checklists), grouped under the three themes Microsoft names plus delivery and operation. The <code>PPSOL-*</code> identifiers are Scout&#39;s. A score from this file is Scout&#39;s questionnaire score against that reading, not the score Microsoft&#39;s assessment would return.</p><h2 id="scout-does-not-read-power-platform-data-yet" tabindex="-1">Scout does not read Power Platform data yet <a class="header-anchor" href="#scout-does-not-read-power-platform-data-yet" aria-label="Permalink to &quot;Scout does not read Power Platform data yet&quot;">​</a></h2><p>Scout collects Azure Resource Manager, Resource Graph and a small set of Microsoft Graph data. It does not call the Power Platform admin APIs, so it has no inventory of environments, data policies, apps or flows. All 37 items are therefore <strong>manual</strong>: each rule has <code>manual: true</code> and <code>query: null</code>, and the answer comes from the questionnaire (<a href="./../assessment/questionnaire-answers.html">Questionnaire Answers</a>). Unanswered items show as Manual and are left out of the score; they are never counted as failures. No rule reads <code>collect.json</code>.</p><p>Sources:</p><p>Read in full with the Microsoft Learn MCP <code>microsoft_docs_fetch</code> tool on 2026-11-25:</p><ul><li><a href="https://learn.microsoft.com/power-platform/guidance/" target="_blank" rel="noreferrer">https://learn.microsoft.com/power-platform/guidance/</a></li><li><a href="https://learn.microsoft.com/power-platform/guidance/adoption/admin-best-practices" target="_blank" rel="noreferrer">https://learn.microsoft.com/power-platform/guidance/adoption/admin-best-practices</a></li><li><a href="https://learn.microsoft.com/power-platform/guidance/adoption/availability-overview" target="_blank" rel="noreferrer">https://learn.microsoft.com/power-platform/guidance/adoption/availability-overview</a></li><li><a href="https://learn.microsoft.com/power-platform/guidance/adoption/govern-at-scale" target="_blank" rel="noreferrer">https://learn.microsoft.com/power-platform/guidance/adoption/govern-at-scale</a></li><li><a href="https://learn.microsoft.com/power-platform/guidance/adoption/observability" target="_blank" rel="noreferrer">https://learn.microsoft.com/power-platform/guidance/adoption/observability</a></li><li><a href="https://learn.microsoft.com/power-platform/guidance/adoption/operate-overview" target="_blank" rel="noreferrer">https://learn.microsoft.com/power-platform/guidance/adoption/operate-overview</a></li><li><a href="https://learn.microsoft.com/power-platform/guidance/adoption/ready-overview" target="_blank" rel="noreferrer">https://learn.microsoft.com/power-platform/guidance/adoption/ready-overview</a></li><li><a href="https://learn.microsoft.com/power-platform/guidance/adoption/solution-envisioning" target="_blank" rel="noreferrer">https://learn.microsoft.com/power-platform/guidance/adoption/solution-envisioning</a></li><li><a href="https://learn.microsoft.com/power-platform/guidance/adoption/strategy-best-practices" target="_blank" rel="noreferrer">https://learn.microsoft.com/power-platform/guidance/adoption/strategy-best-practices</a></li><li><a href="https://learn.microsoft.com/power-platform/well-architected/experience-optimization/checklist" target="_blank" rel="noreferrer">https://learn.microsoft.com/power-platform/well-architected/experience-optimization/checklist</a></li><li><a href="https://learn.microsoft.com/power-platform/well-architected/operational-excellence/checklist" target="_blank" rel="noreferrer">https://learn.microsoft.com/power-platform/well-architected/operational-excellence/checklist</a></li><li><a href="https://learn.microsoft.com/power-platform/well-architected/performance-efficiency/checklist" target="_blank" rel="noreferrer">https://learn.microsoft.com/power-platform/well-architected/performance-efficiency/checklist</a></li><li><a href="https://learn.microsoft.com/power-platform/well-architected/pillars" target="_blank" rel="noreferrer">https://learn.microsoft.com/power-platform/well-architected/pillars</a></li><li><a href="https://learn.microsoft.com/power-platform/well-architected/reliability/checklist" target="_blank" rel="noreferrer">https://learn.microsoft.com/power-platform/well-architected/reliability/checklist</a></li><li><a href="https://learn.microsoft.com/power-platform/well-architected/security/checklist" target="_blank" rel="noreferrer">https://learn.microsoft.com/power-platform/well-architected/security/checklist</a></li></ul><p>Cited per item, but read only as the title and one-line summary on the overview pages above, or as a Microsoft Learn search excerpt. The article itself was not opened in full:</p><ul><li><a href="https://learn.microsoft.com/microsoft-copilot-studio/guidance/alm" target="_blank" rel="noreferrer">https://learn.microsoft.com/microsoft-copilot-studio/guidance/alm</a></li><li><a href="https://learn.microsoft.com/power-platform/alm/overview-alm" target="_blank" rel="noreferrer">https://learn.microsoft.com/power-platform/alm/overview-alm</a></li><li><a href="https://learn.microsoft.com/power-platform/guidance/adoption/alm" target="_blank" rel="noreferrer">https://learn.microsoft.com/power-platform/guidance/adoption/alm</a></li><li><a href="https://learn.microsoft.com/power-platform/guidance/adoption/application-modernization" target="_blank" rel="noreferrer">https://learn.microsoft.com/power-platform/guidance/adoption/application-modernization</a></li><li><a href="https://learn.microsoft.com/power-platform/guidance/adoption/business-value" target="_blank" rel="noreferrer">https://learn.microsoft.com/power-platform/guidance/adoption/business-value</a></li><li><a href="https://learn.microsoft.com/power-platform/guidance/adoption/cds-usage" target="_blank" rel="noreferrer">https://learn.microsoft.com/power-platform/guidance/adoption/cds-usage</a></li><li><a href="https://learn.microsoft.com/power-platform/guidance/adoption/data-retention" target="_blank" rel="noreferrer">https://learn.microsoft.com/power-platform/guidance/adoption/data-retention</a></li><li><a href="https://learn.microsoft.com/power-platform/guidance/adoption/dlp-strategy" target="_blank" rel="noreferrer">https://learn.microsoft.com/power-platform/guidance/adoption/dlp-strategy</a></li><li><a href="https://learn.microsoft.com/power-platform/guidance/adoption/environment-strategy" target="_blank" rel="noreferrer">https://learn.microsoft.com/power-platform/guidance/adoption/environment-strategy</a></li><li><a href="https://learn.microsoft.com/power-platform/guidance/adoption/license-assignment-strategies" target="_blank" rel="noreferrer">https://learn.microsoft.com/power-platform/guidance/adoption/license-assignment-strategies</a></li><li><a href="https://learn.microsoft.com/power-platform/guidance/adoption/plan-disaster-recovery" target="_blank" rel="noreferrer">https://learn.microsoft.com/power-platform/guidance/adoption/plan-disaster-recovery</a></li><li><a href="https://learn.microsoft.com/power-platform/guidance/adoption/plan-mission-critical" target="_blank" rel="noreferrer">https://learn.microsoft.com/power-platform/guidance/adoption/plan-mission-critical</a></li><li><a href="https://learn.microsoft.com/power-platform/guidance/adoption/roles" target="_blank" rel="noreferrer">https://learn.microsoft.com/power-platform/guidance/adoption/roles</a></li><li><a href="https://learn.microsoft.com/power-platform/guidance/adoption/support-strategy" target="_blank" rel="noreferrer">https://learn.microsoft.com/power-platform/guidance/adoption/support-strategy</a></li><li><a href="https://learn.microsoft.com/power-platform/guidance/adoption/training-strategy" target="_blank" rel="noreferrer">https://learn.microsoft.com/power-platform/guidance/adoption/training-strategy</a></li></ul><h2 id="the-enumeration-—-37-items-across-5-groups" tabindex="-1">The enumeration — 37 items across 5 groups <a class="header-anchor" href="#the-enumeration-—-37-items-across-5-groups" aria-label="Permalink to &quot;The enumeration — 37 items across 5 groups&quot;">​</a></h2><h3 id="business-alignment-ppsol-bg-—-6-items" tabindex="-1">Business alignment (PPSOL-BG) — 6 items <a class="header-anchor" href="#business-alignment-ppsol-bg-—-6-items" aria-label="Permalink to &quot;Business alignment (PPSOL-BG) — 6 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>PPSOL-BG-01</td><td>The solution has documented business objectives and measurable success criteria agreed before build</td><td>Manual — questionnaire</td><td><a href="https://learn.microsoft.com/power-platform/guidance/adoption/alm" target="_blank" rel="noreferrer">power-platform/guidance/adoption/alm</a><br><a href="https://learn.microsoft.com/power-platform/guidance/adoption/business-value" target="_blank" rel="noreferrer">power-platform/guidance/adoption/business-value</a></td></tr><tr><td>PPSOL-BG-02</td><td>A business owner and an executive sponsor are named for the solution</td><td>Manual — questionnaire</td><td><a href="https://learn.microsoft.com/power-platform/guidance/adoption/strategy-best-practices" target="_blank" rel="noreferrer">power-platform/guidance/adoption/strategy-best-practices</a><br><a href="https://learn.microsoft.com/power-platform/guidance/adoption/roles" target="_blank" rel="noreferrer">power-platform/guidance/adoption/roles</a></td></tr><tr><td>PPSOL-BG-03</td><td>Business, IT, end-user and compliance stakeholders took part in defining the solution</td><td>Manual — questionnaire</td><td><a href="https://learn.microsoft.com/power-platform/guidance/adoption/solution-envisioning" target="_blank" rel="noreferrer">power-platform/guidance/adoption/solution-envisioning</a></td></tr><tr><td>PPSOL-BG-04</td><td>The solution&#39;s business value is measured and reported after go-live</td><td>Manual — questionnaire</td><td><a href="https://learn.microsoft.com/power-platform/guidance/adoption/business-value" target="_blank" rel="noreferrer">power-platform/guidance/adoption/business-value</a></td></tr><tr><td>PPSOL-BG-05</td><td>Power Platform was chosen deliberately against alternatives, and the level of formality is set by the solution&#39;s complexity and criticality</td><td>Manual — questionnaire</td><td><a href="https://learn.microsoft.com/power-platform/guidance/adoption/alm" target="_blank" rel="noreferrer">power-platform/guidance/adoption/alm</a><br><a href="https://learn.microsoft.com/power-platform/guidance/adoption/application-modernization" target="_blank" rel="noreferrer">power-platform/guidance/adoption/application-modernization</a></td></tr><tr><td>PPSOL-BG-06</td><td>The solution is classified by criticality and the classification sets its availability, support and recovery requirements</td><td>Manual — questionnaire</td><td><a href="https://learn.microsoft.com/power-platform/guidance/adoption/plan-mission-critical" target="_blank" rel="noreferrer">power-platform/guidance/adoption/plan-mission-critical</a><br><a href="https://learn.microsoft.com/power-platform/guidance/adoption/availability-overview" target="_blank" rel="noreferrer">power-platform/guidance/adoption/availability-overview</a></td></tr></tbody></table><h3 id="functionality-and-design-ppsol-fn-—-10-items" tabindex="-1">Functionality and design (PPSOL-FN) — 10 items <a class="header-anchor" href="#functionality-and-design-ppsol-fn-—-10-items" aria-label="Permalink to &quot;Functionality and design (PPSOL-FN) — 10 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>PPSOL-FN-01</td><td>Requirements are captured, prioritised by business value and traceable to solution components</td><td>Manual — questionnaire</td><td><a href="https://learn.microsoft.com/power-platform/guidance/adoption/alm" target="_blank" rel="noreferrer">power-platform/guidance/adoption/alm</a><br><a href="https://learn.microsoft.com/power-platform/well-architected/operational-excellence/checklist" target="_blank" rel="noreferrer">power-platform/well-architected/operational-excellence/checklist</a></td></tr><tr><td>PPSOL-FN-02</td><td>All components (apps, flows, agents, tables and other assets) are held in Dataverse solutions rather than built loose</td><td>Manual — questionnaire</td><td><a href="https://learn.microsoft.com/power-platform/alm/overview-alm" target="_blank" rel="noreferrer">power-platform/alm/overview-alm</a><br><a href="https://learn.microsoft.com/power-platform/guidance/adoption/environment-strategy" target="_blank" rel="noreferrer">power-platform/guidance/adoption/environment-strategy</a></td></tr><tr><td>PPSOL-FN-03</td><td>The data model is designed deliberately, with the data store, tables and relationships chosen and documented for the workload</td><td>Manual — questionnaire</td><td><a href="https://learn.microsoft.com/power-platform/well-architected/performance-efficiency/checklist" target="_blank" rel="noreferrer">power-platform/well-architected/performance-efficiency/checklist</a><br><a href="https://learn.microsoft.com/power-platform/alm/overview-alm" target="_blank" rel="noreferrer">power-platform/alm/overview-alm</a></td></tr><tr><td>PPSOL-FN-04</td><td>Security roles and sharing follow least privilege for each type of user</td><td>Manual — questionnaire</td><td><a href="https://learn.microsoft.com/power-platform/well-architected/security/checklist" target="_blank" rel="noreferrer">power-platform/well-architected/security/checklist</a><br><a href="https://learn.microsoft.com/power-platform/guidance/adoption/roles" target="_blank" rel="noreferrer">power-platform/guidance/adoption/roles</a></td></tr><tr><td>PPSOL-FN-05</td><td>Connectors and connections are approved under the tenant data policies, and shared solutions use service identities rather than a maker&#39;s personal connection</td><td>Manual — questionnaire</td><td><a href="https://learn.microsoft.com/power-platform/guidance/adoption/dlp-strategy" target="_blank" rel="noreferrer">power-platform/guidance/adoption/dlp-strategy</a><br><a href="https://learn.microsoft.com/power-platform/guidance/adoption/govern-at-scale" target="_blank" rel="noreferrer">power-platform/guidance/adoption/govern-at-scale</a></td></tr><tr><td>PPSOL-FN-06</td><td>Environment-specific settings are held in environment variables and connection references, not hard-coded</td><td>Manual — questionnaire</td><td><a href="https://learn.microsoft.com/microsoft-copilot-studio/guidance/alm" target="_blank" rel="noreferrer">microsoft-copilot-studio/guidance/alm</a><br><a href="https://learn.microsoft.com/power-platform/alm/overview-alm" target="_blank" rel="noreferrer">power-platform/alm/overview-alm</a></td></tr><tr><td>PPSOL-FN-07</td><td>Integrations with other systems are documented, with error handling and platform request limits taken into account</td><td>Manual — questionnaire</td><td><a href="https://learn.microsoft.com/power-platform/well-architected/reliability/checklist" target="_blank" rel="noreferrer">power-platform/well-architected/reliability/checklist</a><br><a href="https://learn.microsoft.com/power-platform/well-architected/performance-efficiency/checklist" target="_blank" rel="noreferrer">power-platform/well-architected/performance-efficiency/checklist</a></td></tr><tr><td>PPSOL-FN-08</td><td>Licences needed by every user and component (premium connectors, per-user or per-app, capacity) are identified before rollout</td><td>Manual — questionnaire</td><td><a href="https://learn.microsoft.com/power-platform/guidance/adoption/license-assignment-strategies" target="_blank" rel="noreferrer">power-platform/guidance/adoption/license-assignment-strategies</a><br><a href="https://learn.microsoft.com/power-platform/guidance/adoption/cds-usage" target="_blank" rel="noreferrer">power-platform/guidance/adoption/cds-usage</a></td></tr><tr><td>PPSOL-FN-09</td><td>Apps and flows have a named owner, and ownership survives a maker leaving</td><td>Manual — questionnaire</td><td><a href="https://learn.microsoft.com/power-platform/guidance/adoption/roles" target="_blank" rel="noreferrer">power-platform/guidance/adoption/roles</a><br><a href="https://learn.microsoft.com/power-platform/guidance/adoption/govern-at-scale" target="_blank" rel="noreferrer">power-platform/guidance/adoption/govern-at-scale</a></td></tr><tr><td>PPSOL-FN-10</td><td>AI components (agents, AI Builder models, Copilot features) have a defined purpose, boundaries, human oversight and a responsible-AI review</td><td>Manual — questionnaire</td><td><a href="https://learn.microsoft.com/power-platform/guidance/adoption/solution-envisioning" target="_blank" rel="noreferrer">power-platform/guidance/adoption/solution-envisioning</a><br><a href="https://learn.microsoft.com/power-platform/well-architected/experience-optimization/checklist" target="_blank" rel="noreferrer">power-platform/well-architected/experience-optimization/checklist</a></td></tr></tbody></table><h3 id="user-experience-ppsol-ux-—-8-items" tabindex="-1">User experience (PPSOL-UX) — 8 items <a class="header-anchor" href="#user-experience-ppsol-ux-—-8-items" aria-label="Permalink to &quot;User experience (PPSOL-UX) — 8 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>PPSOL-UX-01</td><td>The target users and their tasks are identified, and users were involved in the design</td><td>Manual — questionnaire</td><td><a href="https://learn.microsoft.com/power-platform/well-architected/experience-optimization/checklist" target="_blank" rel="noreferrer">power-platform/well-architected/experience-optimization/checklist</a></td></tr><tr><td>PPSOL-UX-02</td><td>The interface follows consistent design standards, navigation and terminology</td><td>Manual — questionnaire</td><td><a href="https://learn.microsoft.com/power-platform/well-architected/experience-optimization/checklist" target="_blank" rel="noreferrer">power-platform/well-architected/experience-optimization/checklist</a></td></tr><tr><td>PPSOL-UX-03</td><td>Accessibility needs are designed for and tested</td><td>Manual — questionnaire</td><td><a href="https://learn.microsoft.com/power-platform/well-architected/experience-optimization/checklist" target="_blank" rel="noreferrer">power-platform/well-architected/experience-optimization/checklist</a></td></tr><tr><td>PPSOL-UX-04</td><td>The layout works on the devices and screen sizes users have</td><td>Manual — questionnaire</td><td><a href="https://learn.microsoft.com/power-platform/well-architected/experience-optimization/checklist" target="_blank" rel="noreferrer">power-platform/well-architected/experience-optimization/checklist</a></td></tr><tr><td>PPSOL-UX-05</td><td>App and flow response times meet defined targets and are measured with real users</td><td>Manual — questionnaire</td><td><a href="https://learn.microsoft.com/power-platform/well-architected/performance-efficiency/checklist" target="_blank" rel="noreferrer">power-platform/well-architected/performance-efficiency/checklist</a></td></tr><tr><td>PPSOL-UX-06</td><td>Messages, notifications and errors tell users what happened and what to do next</td><td>Manual — questionnaire</td><td><a href="https://learn.microsoft.com/power-platform/well-architected/experience-optimization/checklist" target="_blank" rel="noreferrer">power-platform/well-architected/experience-optimization/checklist</a></td></tr><tr><td>PPSOL-UX-07</td><td>Users are onboarded with training and help content for the solution</td><td>Manual — questionnaire</td><td><a href="https://learn.microsoft.com/power-platform/guidance/adoption/training-strategy" target="_blank" rel="noreferrer">power-platform/guidance/adoption/training-strategy</a><br><a href="https://learn.microsoft.com/power-platform/guidance/adoption/ready-overview" target="_blank" rel="noreferrer">power-platform/guidance/adoption/ready-overview</a></td></tr><tr><td>PPSOL-UX-08</td><td>Users have a channel for feedback and enhancement requests, and it is acted on</td><td>Manual — questionnaire</td><td><a href="https://learn.microsoft.com/power-platform/guidance/adoption/govern-at-scale" target="_blank" rel="noreferrer">power-platform/guidance/adoption/govern-at-scale</a><br><a href="https://learn.microsoft.com/power-platform/well-architected/experience-optimization/checklist" target="_blank" rel="noreferrer">power-platform/well-architected/experience-optimization/checklist</a></td></tr></tbody></table><h3 id="delivery-and-alm-ppsol-dl-—-8-items" tabindex="-1">Delivery and ALM (PPSOL-DL) — 8 items <a class="header-anchor" href="#delivery-and-alm-ppsol-dl-—-8-items" aria-label="Permalink to &quot;Delivery and ALM (PPSOL-DL) — 8 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>PPSOL-DL-01</td><td>Separate development, test and production environments are used</td><td>Manual — questionnaire</td><td><a href="https://learn.microsoft.com/power-platform/alm/overview-alm" target="_blank" rel="noreferrer">power-platform/alm/overview-alm</a><br><a href="https://learn.microsoft.com/power-platform/guidance/adoption/environment-strategy" target="_blank" rel="noreferrer">power-platform/guidance/adoption/environment-strategy</a></td></tr><tr><td>PPSOL-DL-02</td><td>Solutions are held in source control as the source of truth</td><td>Manual — questionnaire</td><td><a href="https://learn.microsoft.com/power-platform/alm/overview-alm" target="_blank" rel="noreferrer">power-platform/alm/overview-alm</a><br><a href="https://learn.microsoft.com/power-platform/guidance/adoption/application-modernization" target="_blank" rel="noreferrer">power-platform/guidance/adoption/application-modernization</a></td></tr><tr><td>PPSOL-DL-03</td><td>Deployments between environments are automated through pipelines</td><td>Manual — questionnaire</td><td><a href="https://learn.microsoft.com/power-platform/guidance/adoption/alm" target="_blank" rel="noreferrer">power-platform/guidance/adoption/alm</a><br><a href="https://learn.microsoft.com/power-platform/guidance/adoption/application-modernization" target="_blank" rel="noreferrer">power-platform/guidance/adoption/application-modernization</a></td></tr><tr><td>PPSOL-DL-04</td><td>Solution checker, or an equivalent static check, is run and its findings resolved before deployment</td><td>Manual — questionnaire</td><td><a href="https://learn.microsoft.com/power-platform/guidance/adoption/environment-strategy" target="_blank" rel="noreferrer">power-platform/guidance/adoption/environment-strategy</a></td></tr><tr><td>PPSOL-DL-05</td><td>Managed solutions with version numbers are deployed to test and production</td><td>Manual — questionnaire</td><td><a href="https://learn.microsoft.com/power-platform/alm/overview-alm" target="_blank" rel="noreferrer">power-platform/alm/overview-alm</a></td></tr><tr><td>PPSOL-DL-06</td><td>Functional, regression and user acceptance testing are defined and performed before release</td><td>Manual — questionnaire</td><td><a href="https://learn.microsoft.com/power-platform/well-architected/operational-excellence/checklist" target="_blank" rel="noreferrer">power-platform/well-architected/operational-excellence/checklist</a><br><a href="https://learn.microsoft.com/power-platform/guidance/adoption/alm" target="_blank" rel="noreferrer">power-platform/guidance/adoption/alm</a></td></tr><tr><td>PPSOL-DL-07</td><td>A rollback or feature-disable plan exists for failed releases</td><td>Manual — questionnaire</td><td><a href="https://learn.microsoft.com/power-platform/well-architected/operational-excellence/checklist" target="_blank" rel="noreferrer">power-platform/well-architected/operational-excellence/checklist</a></td></tr><tr><td>PPSOL-DL-08</td><td>Design, data model and support runbook documentation is current</td><td>Manual — questionnaire</td><td><a href="https://learn.microsoft.com/power-platform/well-architected/operational-excellence/checklist" target="_blank" rel="noreferrer">power-platform/well-architected/operational-excellence/checklist</a></td></tr></tbody></table><h3 id="operate-ppsol-op-—-5-items" tabindex="-1">Operate (PPSOL-OP) — 5 items <a class="header-anchor" href="#operate-ppsol-op-—-5-items" aria-label="Permalink to &quot;Operate (PPSOL-OP) — 5 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>PPSOL-OP-01</td><td>Solution health is monitored with alerts, using the admin centre Monitor area, Application Insights or an equivalent</td><td>Manual — questionnaire</td><td><a href="https://learn.microsoft.com/power-platform/guidance/adoption/observability" target="_blank" rel="noreferrer">power-platform/guidance/adoption/observability</a></td></tr><tr><td>PPSOL-OP-02</td><td>A support model and escalation path for the solution is defined and known to users</td><td>Manual — questionnaire</td><td><a href="https://learn.microsoft.com/power-platform/guidance/adoption/support-strategy" target="_blank" rel="noreferrer">power-platform/guidance/adoption/support-strategy</a><br><a href="https://learn.microsoft.com/power-platform/guidance/adoption/operate-overview" target="_blank" rel="noreferrer">power-platform/guidance/adoption/operate-overview</a></td></tr><tr><td>PPSOL-OP-03</td><td>Backup, restore and retention for the solution&#39;s environment and data are understood and tested</td><td>Manual — questionnaire</td><td><a href="https://learn.microsoft.com/power-platform/guidance/adoption/data-retention" target="_blank" rel="noreferrer">power-platform/guidance/adoption/data-retention</a><br><a href="https://learn.microsoft.com/power-platform/guidance/adoption/plan-disaster-recovery" target="_blank" rel="noreferrer">power-platform/guidance/adoption/plan-disaster-recovery</a></td></tr><tr><td>PPSOL-OP-04</td><td>Capacity and licence consumption of the solution is monitored</td><td>Manual — questionnaire</td><td><a href="https://learn.microsoft.com/power-platform/guidance/adoption/observability" target="_blank" rel="noreferrer">power-platform/guidance/adoption/observability</a><br><a href="https://learn.microsoft.com/power-platform/guidance/adoption/cds-usage" target="_blank" rel="noreferrer">power-platform/guidance/adoption/cds-usage</a></td></tr><tr><td>PPSOL-OP-05</td><td>Criteria for retiring the solution and its environment are defined</td><td>Manual — questionnaire</td><td><a href="https://learn.microsoft.com/power-platform/guidance/adoption/environment-strategy" target="_blank" rel="noreferrer">power-platform/guidance/adoption/environment-strategy</a><br><a href="https://learn.microsoft.com/power-platform/guidance/adoption/admin-best-practices" target="_blank" rel="noreferrer">power-platform/guidance/adoption/admin-best-practices</a></td></tr></tbody></table><p>PPSOL-UX-03 (accessibility) and PPSOL-DL-05 (managed solutions with version numbers) are Scout additions drawn from the wider ALM and user-experience guidance rather than a line on a published checklist.</p><h2 id="what-an-automated-version-would-need" tabindex="-1">What an automated version would need <a class="header-anchor" href="#what-an-automated-version-would-need" aria-label="Permalink to &quot;What an automated version would need&quot;">​</a></h2><p>Authentication is a different permission surface from the Azure Resource Manager Reader role every other Scout rule reads through: the Power Platform API takes a token for <code>https://api.powerplatform.com/.default</code> issued to a Microsoft Entra app registration, and the admin PowerShell module signs in as a Power Platform administrator. An automated version would therefore be opt-in, like <code>-IncludeDevOps</code>, and every rule reading it would be gated so &quot;switch off&quot; or &quot;no access&quot; reads Not assessed rather than &quot;nothing is configured&quot;.</p><table tabindex="0"><thead><tr><th>Source</th><th>What it would show</th><th>Items it would answer or inform</th></tr></thead><tbody><tr><td>Power Platform API, <code>EnvironmentManagement</code> namespace (<code>EnvironmentManagement.Environments.Read</code>, <code>.Groups.Read</code>, <code>.Settings.Read</code>)</td><td>Environments with type and group membership; environment management settings; backups and business continuity state</td><td>PPSOL-DL-01 (separate stages), PPSOL-OP-03 (backup and restore), PPSOL-OP-05 (inactive environments)</td></tr><tr><td>Dataverse Web API, per environment: the <code>solution</code>, <code>environmentvariabledefinition</code> and <code>connectionreference</code> tables (the <code>ismanaged</code> column shows managed or unmanaged)</td><td>Whether assets sit in solutions, managed versus unmanaged, use of environment variables and connection references</td><td>PPSOL-FN-02, PPSOL-FN-06, PPSOL-DL-05</td></tr><tr><td>Power Platform API, <code>PowerApps.Apps.Read</code> and <code>PowerAutomate.Flows.Read</code></td><td>Apps and flows with owners and state</td><td>PPSOL-FN-09 (ownership), PPSOL-FN-05 (connections in use)</td></tr><tr><td>Admin PowerShell module <code>Microsoft.PowerApps.Administration.PowerShell</code>: <code>Get-DlpPolicy</code>, <code>Get-AdminDlpPolicy</code>, <code>Get-AdminPowerAppConnector</code></td><td>Data policies and the connectors in use, including custom connectors</td><td>PPSOL-FN-05</td></tr><tr><td>Power Platform API, <code>Licensing</code> namespace (<code>Licensing.Allocations.Read</code>, <code>Licensing.BillingPolicies.Read</code>) and the admin centre capacity reports</td><td>Allocations, billing policies and capacity</td><td>PPSOL-FN-08, PPSOL-OP-04</td></tr><tr><td>Power Platform API, <code>Analytics</code> namespace (<code>Analytics.AdvisorRecommendations.Read</code>)</td><td>Admin centre recommended actions for the tenant</td><td>PPSOL-OP-01</td></tr><tr><td>Azure Resource Graph (Scout already reads this)</td><td>Application Insights and Log Analytics resources that a solution could be sending telemetry to; nothing links them to a solution without the admin API</td><td>PPSOL-OP-01</td></tr></tbody></table><p>Most of this assessment will stay a questionnaire whatever is collected. Business alignment (PPSOL-BG), user experience (PPSOL-UX) and testing and documentation (PPSOL-DL-04 to PPSOL-DL-08) describe how a team works, not how a resource is configured. Roughly ten items could be answered or cross-checked from the sources above. Some of these APIs are marked preview on Learn today, so each would need its current status confirmed before a rule relied on it.</p>',30)])])}const h=t(n,[["render",i]]);export{f as __pageData,h as default};
